{
  "schemaVersion": "0.2",
  "slug": "graph-view",
  "name": "GraphView",
  "family": "G",
  "status": "experimental",
  "purpose": "Renders nodes and links as a deterministic ring-layout relationship diagram.",
  "scenarios": [
    "Service dependency overview",
    "Entity relationship preview",
    "Team network snapshot"
  ],
  "props": {
    "nodes": {
      "type": "string",
      "required": true,
      "description": "Array of { id, label } graph nodes."
    },
    "links": {
      "type": "string",
      "required": true,
      "description": "Array of { source, target } id pairs."
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible label for the graph region."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Graph rendered."
    },
    {
      "name": "empty",
      "description": "No nodes provided."
    }
  ],
  "composition": {
    "allowedParents": [
      "page",
      "app-shell",
      "card"
    ],
    "allowedChildren": [
      "flow-node",
      "edge"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use the ring layout for graphs over 40 nodes.",
    "Do not claim force simulation; layout is deterministic."
  ],
  "a11y": {
    "role": "img",
    "keyboard": [],
    "focus": "Node labels are listed in a companion list for screen readers.",
    "labeling": "aria-label summarizes node and link counts.",
    "wcag": [
      "1.1.1",
      "1.3.1"
    ]
  },
  "responsive": {
    "strategy": "Scales to container via viewBox.",
    "breakpoints": {
      "compact": "Scaled down.",
      "medium": "Fits container.",
      "large": "Fits container."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "graph-view",
    "states": [
      "default",
      "empty"
    ],
    "intents": [
      "enumerate-items"
    ]
  }
}

import './styles.css'

export interface GraphNode {
  id: string
  label: string
}

export interface GraphLink {
  source: string
  target: string
}

export interface GraphViewProps {
  nodes: GraphNode[]
  links: GraphLink[]
  label: string
  className?: string
}

const SIZE = 320
const CENTER = SIZE / 2
const RADIUS = 120

/**
 * @complexity time O(n + m) | space O(n) | n = nodes, m = links; ring layout places node i at a fixed angle
 * @guarantees deterministic positions with no simulation; large graphs must paginate or filter upstream
 */
export function GraphView({ nodes, links, label, className }: GraphViewProps) {
  const classes = ['cu-graph-view', className].filter(Boolean).join(' ')
  const positions = new Map<string, { x: number; y: number }>()
  nodes.forEach((node, index) => {
    const angle = (2 * Math.PI * index) / Math.max(1, nodes.length) - Math.PI / 2
    positions.set(node.id, { x: CENTER + RADIUS * Math.cos(angle), y: CENTER + RADIUS * Math.sin(angle) })
  })

  return (
    <div className={classes} data-ai-role="graph-view" data-ai-intent="enumerate-items" data-ai-state={nodes.length === 0 ? 'empty' : 'default'}>
      <svg className="cu-graph-view__svg" viewBox={`0 0 ${SIZE} ${SIZE}`} role="img" aria-label={label}>
        {links.map((link, index) => {
          const from = positions.get(link.source)
          const to = positions.get(link.target)
          if (!from || !to) return null
          return <line key={index} className="cu-graph-view__link" x1={from.x} y1={from.y} x2={to.x} y2={to.y} />
        })}
        {nodes.map((node) => {
          const position = positions.get(node.id)
          if (!position) return null
          return (
            <g key={node.id} className="cu-graph-view__node">
              <circle cx={position.x} cy={position.y} r={16} />
              <text x={position.x} y={position.y + 32} textAnchor="middle" className="cu-graph-view__label">
                {node.label}
              </text>
            </g>
          )
        })}
      </svg>
      <ul className="cu-graph-view__list">
        {nodes.map((node) => (
          <li key={node.id}>{node.label}</li>
        ))}
      </ul>
    </div>
  )
}

.cu-graph-view {
  display: block;
  color: var(--cu-color-fg-default);
}

.cu-graph-view__svg {
  display: block;
  inline-size: 100%;
  max-inline-size: calc(var(--cu-space-3) * 40);
  block-size: auto;
}

.cu-graph-view__link {
  stroke: var(--cu-color-border-default);
  stroke-width: 1.5;
}

.cu-graph-view__node circle {
  fill: color-mix(in srgb, var(--cu-color-palette-brand) 16%, var(--cu-color-background-default));
  stroke: var(--cu-color-palette-brand);
}

.cu-graph-view__label {
  fill: var(--cu-color-fg-default);
  font-size: 0.75rem;
}

.cu-graph-view__list {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}
